def solve(g,s):
    from collections import deque
    d=[-1]*len(g)
    d[s]=0
    q=deque([s])
    while q:
        u=q.popleft()
        for v in g[u]:
            if d[v]<0:
                d[v]=d[u]+1
                q.append(v)
    return d
